	SHLQ    $4, AX
	LEAQ    (DX)(AX*1), AX
	SHLQ    $4, SI
	LEAQ    (DX)(SI*1), SI

rvi_str_clear_loop:
	MOVQ    $0, (AX)
	MOVQ    $0, 8(AX)
	ADDQ    $16, AX
	CMPQ    AX, SI
	JL      rvi_str_clear_loop

rvi_str_clear_done:
	MOVQ    (CF_ARENA_SAVE+0)(DI), AX
	MOVQ    AX, CTX_ARENA_INT_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+8)(DI), AX
	MOVQ    AX, CTX_ARENA_FLT_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+16)(DI), AX
	MOVQ    AX, CTX_ARENA_STR_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+32)(DI), AX
	MOVQ    AX, CTX_ARENA_BOOL_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+40)(DI), AX
	MOVQ    AX, CTX_ARENA_UINT_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+96)(DI), AX
	MOVQ    AX, CTX_ARENA_SLICEBYTE_IDX(R15)

	CMPB    CF_HAS_GENERAL_ALLOC(DI), $0
	JE      rvi_gen_clear_done
	CALL    ·handlerCallInlineClearGeneralBank(SB)
	MOVQ    CTX_FRAME_POINTER(R15), SI
	LEAQ    -1(SI), R13
	MOVQ    CTX_CSTACK_BASE(R15), BX
	MOVQ    $CALLFRAME_SIZE, CX
	MOVQ    R13, DX
	IMULQ   CX, DX
	LEAQ    (BX)(DX*1), R12
rvi_gen_clear_done:

	MOVQ    R13, CTX_FRAME_POINTER(R15)

	MOVQ    CTX_ASM_CI_PTRS(R15), AX
	MOVQ    (AX)(R13*8), AX
	MOVQ    AX, CTX_ASM_CALL_INFO_BASE(R15)

	MOVQ    CF_PROGRAM_COUNTER(R12), R14
	MOVQ    CF_REGS_INTS_PTR(R12), R8
	MOVQ    CF_REGS_FLOATS_PTR(R12), R9

	MOVQ    CF_REGS_STRINGS_PTR(R12), AX
	MOVQ    AX, CTX_STRINGS_BASE(R15)
	MOVQ    CF_REGS_UINTS_PTR(R12), AX
	MOVQ    AX, CTX_UINTS_BASE(R15)
	MOVQ    CF_REGS_BOOLS_PTR(R12), AX
	MOVQ    AX, CTX_BOOLS_BASE(R15)
	MOVQ    CF_REGS_SLICEBYTE_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_BYTE_BASE(R15)
	MOVQ    CF_REGS_SLICESINT_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_INT_BASE(R15)
	MOVQ    CF_REGS_SLICESFLOAT_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_FLOAT_BASE(R15)
	MOVQ    CF_REGS_SLICESSTRING_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_STRING_BASE(R15)
	MOVQ    CF_REGS_SLICESBOOL_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_BOOL_BASE(R15)
	MOVQ    CF_REGS_SLICESUINT_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_UINT_BASE(R15)
	MOVQ    CF_REGS_COMPLEX_PTR(R12), AX
	MOVQ    AX, CTX_COMPLEX_BASE(R15)

	MOVQ    CTX_DISPATCH_SAVES(R15), AX
	MOVQ    R13, CX
	SHLQ    $6, CX
	LEAQ    (AX)(CX*1), AX
	MOVQ    0(AX), R12
	MOVQ    8(AX), R13
	MOVQ    16(AX), R11
	MOVQ    24(AX), CX
	MOVQ    CX, CTX_FLT_CONSTS_BASE(R15)
	MOVQ    32(AX), CX
	MOVQ    CX, CTX_STR_CONSTS_BASE(R15)
	MOVQ    40(AX), CX
	MOVQ    CX, CTX_BOOL_CONSTS_BASE(R15)

	MOVQ    R12, CTX_CODE_BASE(R15)
	MOVQ    R13, CTX_CODE_LEN(R15)
	MOVQ    R14, CTX_PC(R15)
	MOVQ    R8, CTX_INTS_BASE(R15)
	MOVQ    R9, CTX_FLOATS_BASE(R15)
	MOVQ    R11, CTX_INT_CONSTS_BASE(R15)
	DISPATCH_NEXT()

rvi_fallback:
	DECQ    R14
	MOVQ    R14, CTX_PC(R15)
	MOVQ    $EXIT_RETURN_VOID, CTX_EXIT_REASON(R15)
	MOVQ    R14, CTX_EXIT_PC(R15)
	RET     

// handlerTailCallInline handles OpTailCall in-loop via handlerTailCallInlineSubroutine (no exit-reason round-trip).
TEXT ·handlerTailCallInline(SB), NOSPLIT|NOFRAME, $0
	DECQ    R14
	MOVQ    R14, CTX_PC(R15)
	CALL    ·handlerTailCallInlineSubroutine(SB)
	DISPATCH_NEXT()

// handlerTailCallInlineSubroutine performs the asmTailCallExecute round-trip and reloads dispatcher registers; CALLed from handlerTailCallInline.
TEXT ·handlerTailCallInlineSubroutine(SB), NOSPLIT, $24-0
	NO_LOCAL_POINTERS
	MOVQ    R15, 0(SP)
	CALL    ·asmTailCallExecute(SB)
	MOVQ    8(SP), R15
	MOVQ    CTX_PC(R15), R14
	MOVQ    CTX_CODE_BASE(R15), R12
	MOVQ    CTX_CODE_LEN(R15), R13
	MOVQ    CTX_INTS_BASE(R15), R8
	MOVQ    CTX_FLOATS_BASE(R15), R9
	MOVQ    CTX_INT_CONSTS_BASE(R15), R11
	MOVQ    CTX_JUMP_TABLE(R15), R10
	RET
